//! FerroCAD: Toy — a **kernel-free** edition.
//!
//! It links no geometry module at all: the toy workbench is a document object with a
//! `Height` property, a display mesh generated by its app script, and one manipulator
//! (`ferrocad_toy::height_grip`). It exists to show — and test — that the interaction
//! registry is genuinely generic: the shell hosts the toy grip exactly as it hosts the
//! Part fillet arc, and names neither.
//!
//! Run it with `cargo run -p ferrocad_toy` (needs a display; no OCCT).

fn main() {
    ferrocad::run_edition_with(
        "FerroCAD: Toy",
        "ferrocad_toy",
        ferrocad::Contributions::default()
            .with_manipulator(ferrocad_toy::height_grip)
            .with_gizmo(ferrocad_toy::move_gizmo),
    );
}
